import sys

MOD = 10**9 + 7

def solve(n, s):
    stack = []
    for i in range(n):
        if s[i] == ')':
            temp = 0
            while stack[-1] != '(':
                temp += stack.pop()
                stack.pop()
            stack.pop()
            if not stack or stack[-1] == '(':
                stack.append(temp)
            else:
                stack[-1] += temp
        elif s[i] != '(':
            stack.append(int(s[i]))
        else:
            stack.append(s[i])
    return sum(stack) % MOD

def main():
    n = int(sys.stdin.readline().strip())
    s = sys.stdin.readline().strip().split()
    print(solve(n, s))

if __name__ == "__main__":
    main()

