    operations2 = process_input(program2)

    if len(operations1) != len(operations2):
        return 1

    for op1, op2 in zip(operations1, operations2):
        if op1[0] != op2[0]:
            return 1
        if op1[0] == 'D':
            if op1[1] != op2[1]:
                return 1
        elif op1[0] == 'I':
            if op1[1] != op2[1] or op1[2] != op2[2]:
                return 1

    return 0

